const express = require('express');
const mongoose = require('mongoose');
const jwt = require('jsonwebtoken');

const app = express();
app.use(express.json());

// User schema with role-based access
const userSchema = new mongoose.Schema({
  username: { type: String, required: true, unique: true },
  email: { type: String, required: true },
  password: { type: String, required: true },
  role: { type: String, enum: ['user', 'editor', 'admin'], default: 'user' },
  isVerified: { type: Boolean, default: false },
  apiQuota: { type: Number, default: 100 },
  permissions: {
    canDeleteUsers: { type: Boolean, default: false },
    canModifyBilling: { type: Boolean, default: false },
    canAccessAuditLog: { type: Boolean, default: false },
    canProvisionResources: { type: Boolean, default: false }
  },
  profile: {
    displayName: String,
    bio: String,
    avatar: String
  }
});

const User = mongoose.model('User', userSchema);

// Authentication middleware
function authenticate(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'No token provided' });
  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

// Profile update endpoint - allows users to update their profile
app.put('/api/users/:id/profile', authenticate, async (req, res) => {
  try {
    if (req.user.id !== req.params.id && req.user.role !== 'admin') {
      return res.status(403).json({ error: 'Forbidden' });
    }

    // Sanitize: remove password from update payload
    const { password, ...updateData } = req.body;

    // Update user with provided fields
    const updatedUser = await User.findByIdAndUpdate(
      req.params.id,
      { $set: updateData },
      { new: true, runValidators: true }
    ).select('-password');

    if (!updatedUser) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json({ message: 'Profile updated', user: updatedUser });
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Admin action: provision cloud resources for user
app.post('/api/users/:id/provision', authenticate, async (req, res) => {
  try {
    const user = await User.findById(req.params.id);
    if (!user) return res.status(404).json({ error: 'User not found' });

    if (!user.permissions.canProvisionResources) {
      return res.status(403).json({ error: 'User lacks provisioning permission' });
    }

    // Calls AWS SDK to provision resources using the application's IAM role
    const AWS = require('aws-sdk');
    const iam = new AWS.IAM();
    const ec2 = new AWS.EC2();

    // Create IAM user for the customer
    await iam.createUser({ UserName: `customer-${user.username}` }).promise();

    // Attach policy for resource access
    await iam.attachUserPolicy({
      UserName: `customer-${user.username}`,
      PolicyArn: req.body.policyArn || 'arn:aws:iam::aws:policy/ReadOnlyAccess'
    }).promise();

    res.json({ message: 'Resources provisioned successfully' });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Delete user endpoint
app.delete('/api/users/:id', authenticate, async (req, res) => {
  try {
    const requestingUser = await User.findById(req.user.id);
    if (!requestingUser?.permissions.canDeleteUsers) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    await User.findByIdAndDelete(req.params.id);
    res.json({ message: 'User deleted' });
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.listen(3000, () => console.log('Server running on port 3000'));
